+    #[serde(default)]
+    pub chain_id: Option<String>,
+    /// R4: time-to-live in seconds (default 300). Used by the stuck-watchdog
+    /// SOP to detect stuck tasks.
+    #[serde(default = "default_ttl_seconds")]
