+/// R4: Event-driven delegate args parsed from the tool's JSON arguments.
+/// Used to thread project/milestone/chain metadata into the MQTT topic
+/// hierarchy and the `BackgroundDelegateResult`.
+#[derive(Debug, Clone, Default, PartialEq, Eq)]
+pub struct DelegateEventArgs {
+    pub project_id: Option<String>,
+    pub milestone_id: Option<String>,
+    pub chain_id: Option<String>,
+    pub ttl_seconds: u64,
+    pub session_id: Option<String>,
+}
+
+/// Parse the event-driven args from a tool's JSON argument value.
+/// Returns a `DelegateEventArgs` with defaults applied (ttl_seconds=300).
+pub fn parse_delegate_event_args(args: &serde_json::Value) -> DelegateEventArgs {
+    let project_id = args
+        .get("project_id")
+        .and_then(|v| v.as_str())
+        .filter(|s| !s.is_empty())
+        .map(str::to_string);
+    let milestone_id = args
+        .get("milestone_id")
+        .and_then(|v| v.as_str())
+        .filter(|s| !s.is_empty())
+        .map(str::to_string);
+    let chain_id = args
+        .get("chain_id")
+        .and_then(|v| v.as_str())
+        .filter(|s| !s.is_empty())
+        .map(str::to_string);
+    let ttl_seconds = args
+        .get("ttl_seconds")
+        .and_then(|v| v.as_u64())
+        .unwrap_or(default_ttl_seconds());
+    let session_id = args
+        .get("session_id")
+        .and_then(|v| v.as_str())
+        .filter(|s| !s.is_empty())
+        .map(str::to_string);
+    DelegateEventArgs {
+        project_id,
+        milestone_id,
+        chain_id,
+        ttl_seconds,
+        session_id,
+    }
 }

